window.MG_LAZY_DATA["data/lazy/owner-resources/b481-647c3228d6375181.json"]={sha256:"647c3228d6375181afd1e6270565c5eaa683e59a4e17600d936ca03aab376fb6",value:{"sources":[{"id":"b-src-environment","title":"Research on Innovative and Alternative Wastewater Technologies","url":"https://www.epa.gov/sustainable-water-infrastructure/research-innovative-and-alternative-wastewater-technologies","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: wastewater technologies and treatment references. Not individual verification of every named environmental project."},{"id":"b-src-waste","title":"Sustainable Materials Management","url":"https://www.epa.gov/smm","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: materials life cycles, waste prevention, recycling and recovery."},{"id":"b-src-wastewater","title":"Wastewater Technology Fact Sheets","url":"https://www.epa.gov/septic/wastewater-technology-fact-sheets","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: disinfection, constructed wetlands, package plants, sewer technologies and treatment."},{"id":"v17s-waste-wi","title":"歐盟 JRC 廢棄物焚化 BREF（2019）","titleEn":"JRC Waste Incineration BREF (2019)","url":"https://publications.jrc.ec.europa.eu/repository/handle/JRC118637","organization":"European Commission Joint Research Centre","accessed":"2026-10-23","publisher":"European Commission Joint Research Centre","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-waste-wiindex","title":"歐盟廢棄物焚化技術參考入口","titleEn":"EU Waste Incineration reference","url":"https://bureau-industrial-transformation.jrc.ec.europa.eu/reference/waste-incineration-0","organization":"European Commission Joint Research Centre","accessed":"2026-10-23","publisher":"European Commission Joint Research Centre","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-waste-tclp","title":"EPA SW-846 方法 1311：TCLP","titleEn":"EPA SW-846 Method 1311: TCLP","url":"https://www.epa.gov/hw-sw846/sw-846-test-method-1311-toxicity-characteristic-leaching-procedure","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."}],"media":{"courses":[{"courseId":"b481","videos":[],"guides":[{"id":"b481-v17-practice","title":"工程操作與定量驗證手冊","titleEn":"Engineering actions and quantitative verification","concept":"本課以「以粒徑、解離度和品位回收率設計底渣金屬分選的教學流程」為主軸，依序處理底渣批次與金屬基準、鐵磁性金屬回收、含水與細泥附著、礦物產物浸出評估、分選用電與資源效益。十個單元各包含機制、算例、量測驗證及失效診斷；數值均為明示的原創教學假設，不能直接用作工程設計、排放限值或設備設定。","conceptEn":"This course focuses on Build a bottom-ash metal-separation workflow around size, liberation and grade-recovery evidence, progressing through Bottom-ash batches and metal basis, Ferromagnetic metal recovery, Moisture and adhering fines, Leaching of mineral products, Separation electricity and resource benefit. Ten units each address mechanism, worked calculation, measurement verification and failure diagnosis. Numbers are explicit original teaching assumptions, not design values, emission limits or equipment settings.","procedure":["只將 f 改成 0.22，其餘輸入固定。重算結果應由 180 變成 220 kg。先預測方向，再核對單位與假設；用離線模擬或已提供資料完成，不操作現場設備。","只將 r 改成 0.70，其餘輸入固定。重算結果應由 270 變成 210 kg。先預測方向，再核對單位與假設；用離線模擬或已提供資料完成，不操作現場設備。","只將 r 改成 0.85，其餘輸入固定。重算結果應由 60 變成 68 kg。先預測方向，再核對單位與假設；用離線模擬或已提供資料完成，不操作現場設備。","只將非目標物增加 10 kg，mt 不變，其餘輸入固定。重算結果應由 75 變成 66.6667 %。先預測方向，再核對單位與假設；用離線模擬或已提供資料完成，不操作現場設備。","只將濕基含水率 w 改成 0.40，其餘輸入固定。重算結果應由 700 變成 600 kg dry solids。先預測方向，再核對單位與假設；用離線模擬或已提供資料完成，不操作現場設備。","只將 r 改成 0.85，其餘輸入固定。重算結果應由 60 變成 68 kg。先預測方向，再核對單位與假設；用離線模擬或已提供資料完成，不操作現場設備。","只將 C 改成 3 mg/L，其餘輸入固定。重算結果應由 40 變成 60 mg/kg dry sample。先預測方向，再核對單位與假設；用離線模擬或已提供資料完成，不操作現場設備。","只將 Q 改成 12000 Nm³/h，其餘輸入固定。重算結果應由 0.2 變成 0.24 kg/h。先預測方向，再核對單位與假設；用離線模擬或已提供資料完成，不操作現場設備。","只將 f 改成 0.2 kg CO₂e/kWh，其餘輸入固定。重算結果應由 80 變成 40 kg CO₂e/t。先預測方向，再核對單位與假設；用離線模擬或已提供資料完成，不操作現場設備。","只將 uC 改成 0.03，其餘輸入固定。重算結果應由 0.072111 變成 0.05 relative standard uncertainty。先預測方向，再核對單位與假設；用離線模擬或已提供資料完成，不操作現場設備。"],"procedureEn":["Change only f to 0.22, holding all other inputs fixed. Recalculation changes 180 to 220 kg. Predict the direction first, then check units and assumptions; use offline simulation or supplied data without operating field equipment.","Change only capture r to 0.70, holding all other inputs fixed. Recalculation changes 270 to 210 kg. Predict the direction first, then check units and assumptions; use offline simulation or supplied data without operating field equipment.","Change only recovery r to 0.85, holding all other inputs fixed. Recalculation changes 60 to 68 kg. Predict the direction first, then check units and assumptions; use offline simulation or supplied data without operating field equipment.","Add only 10 kg non-target material, holding mt fixed, holding all other inputs fixed. Recalculation changes 75 to 66.6667 %. Predict the direction first, then check units and assumptions; use offline simulation or supplied data without operating field equipment.","Change only wet-basis moisture w to 0.40, holding all other inputs fixed. Recalculation changes 700 to 600 kg dry solids. Predict the direction first, then check units and assumptions; use offline simulation or supplied data without operating field equipment.","Change only recovery r to 0.85, holding all other inputs fixed. Recalculation changes 60 to 68 kg. Predict the direction first, then check units and assumptions; use offline simulation or supplied data without operating field equipment.","Change only C to 3 mg/L, holding all other inputs fixed. Recalculation changes 40 to 60 mg/kg dry sample. Predict the direction first, then check units and assumptions; use offline simulation or supplied data without operating field equipment.","Change only Q to 12000 Nm³/h, holding all other inputs fixed. Recalculation changes 0.2 to 0.24 kg/h. Predict the direction first, then check units and assumptions; use offline simulation or supplied data without operating field equipment.","Change only grid factor f to 0.2 kg CO₂e/kWh, holding all other inputs fixed. Recalculation changes 80 to 40 kg CO₂e/t. Predict the direction first, then check units and assumptions; use offline simulation or supplied data without operating field equipment.","Change only uC to 0.03, holding all other inputs fixed. Recalculation changes 0.072111 to 0.05 relative standard uncertainty. Predict the direction first, then check units and assumptions; use offline simulation or supplied data without operating field equipment."],"evidence":["針對「底渣批次與金屬基準」，秤總樣與分離後成分，保存含水率與分樣方式，檢查回收率。 保存原始資料、單位與校正日期，以本步模型和另一種可能原因比較。","針對「粒徑分級與篩分」，分別量進料與兩出口的粒徑分布，檢查堵孔、含水與旁通。 保存原始資料、單位與校正日期，以本步模型和另一種可能原因比較。","針對「鐵磁性金屬回收」，對進料、產品及尾料分別秤重化驗，求回收率與純度並關閉金屬收支。 保存原始資料、單位與校正日期，以本步模型和另一種可能原因比較。","針對「非鐵金屬渦電流分選」，用產品分樣和尾料分析建立品位—回收率曲線，而非只報單一指標。 保存原始資料、單位與校正日期，以本步模型和另一種可能原因比較。","針對「含水與細泥附著」，保存稱重、乾燥方法及分樣紀錄，對比重複樣並檢查非水揮發損失。 保存原始資料、單位與校正日期，以本步模型和另一種可能原因比較。","針對「細粒金屬損失」，對進料、產品及尾料分別秤重化驗，求回收率與純度並關閉金屬收支。 保存原始資料、單位與校正日期，以本步模型和另一種可能原因比較。","針對「礦物產物浸出評估」，記錄方法、空白、液固比和乾重，將浸出 mg/L 與換算 mg/kg 分欄呈現。 保存原始資料、單位與校正日期，以本步模型和另一種可能原因比較。","針對「粉塵捕集與外逸」，查驗溫壓、含濕率及濃度報表欄位，再核對煙道流速與面積。 保存原始資料、單位與校正日期，以本步模型和另一種可能原因比較。","針對「分選用電與資源效益」，保存電表邊界、產量與係數版本，對替代電力情境作敏感度分析。 保存原始資料、單位與校正日期，以本步模型和另一種可能原因比較。","針對「品位回收率交接」，建立每項不確定度來源表，將重複性、校正和代表性分開，檢查相關性。 保存原始資料、單位與校正日期，以本步模型和另一種可能原因比較。"],"evidenceEn":["For Bottom-ash batches and metal basis, Weigh the bulk sample and separated fraction; retain moisture basis and sampling procedure and check recovery. Retain raw data, units and calibration date; compare the model with one alternative explanation.","For Size classes and screening, Measure feed and both outlet size distributions, checking blinded apertures, moisture and bypass. Retain raw data, units and calibration date; compare the model with one alternative explanation.","For Ferromagnetic metal recovery, Weigh and assay feed, product and tailings; calculate recovery and purity and close the metal balance. Retain raw data, units and calibration date; compare the model with one alternative explanation.","For Nonferrous eddy-current separation, Build grade-recovery curves from product subsamples and tail assays rather than reporting one metric. Retain raw data, units and calibration date; compare the model with one alternative explanation.","For Moisture and adhering fines, Retain weighing, drying method and subsampling records and compare duplicates while checking non-water volatile loss. Retain raw data, units and calibration date; compare the model with one alternative explanation.","For Fine-metal losses, Weigh and assay feed, product and tailings; calculate recovery and purity and close the metal balance. Retain raw data, units and calibration date; compare the model with one alternative explanation.","For Leaching of mineral products, Record method, blanks, liquid/solid ratio and dry mass; display leachate mg/L separately from converted mg/kg. Retain raw data, units and calibration date; compare the model with one alternative explanation.","For Dust collection and escape, Check temperature, pressure, moisture and concentration-report bases, then verify duct velocity and area. Retain raw data, units and calibration date; compare the model with one alternative explanation.","For Separation electricity and resource benefit, Record metering boundary, output and factor version; test alternative electricity scenarios. Retain raw data, units and calibration date; compare the model with one alternative explanation.","For Grade-recovery handoff, Build an uncertainty budget separating repeatability, calibration and representativeness; inspect correlations. Retain raw data, units and calibration date; compare the model with one alternative explanation."],"pitfalls":["濕基與乾基混用會令回收物或負荷被高估。 在「底渣批次與金屬基準」的流程圖圈出錯誤可能進入的位置，再指定能區分原因的量測。","濕料結團讓可回收細粒留在粗料中。 在「粒徑分級與篩分」的流程圖圈出錯誤可能進入的位置，再指定能區分原因的量測。","提高產品總重量可能只是混入更多非金屬。 在「鐵磁性金屬回收」的流程圖圈出錯誤可能進入的位置，再指定能區分原因的量測。","夾帶濕泥或礦物使重量看似增加，卻降低可售品質。 在「非鐵金屬渦電流分選」的流程圖圈出錯誤可能進入的位置，再指定能區分原因的量測。","用濕重比較處理前後會把脫水誤認為固體去除。 在「含水與細泥附著」的流程圖圈出錯誤可能進入的位置，再指定能區分原因的量測。","提高產品總重量可能只是混入更多非金屬。 在「細粒金屬損失」的流程圖圈出錯誤可能進入的位置，再指定能區分原因的量測。","浸出液 mg/L 誤標成固體 mg/kg 會改變結論。 在「礦物產物浸出評估」的流程圖圈出錯誤可能進入的位置，再指定能區分原因的量測。","標準氣量和實際體積流量混乘會系統性偏差。 在「粉塵捕集與外逸」的流程圖圈出錯誤可能進入的位置，再指定能區分原因的量測。","把不同年份或系統邊界的係數混用會產生假比較。 在「分選用電與資源效益」的流程圖圈出錯誤可能進入的位置，再指定能區分原因的量測。","增加同偏差的重複測量不能消除系統性誤差。 在「品位回收率交接」的流程圖圈出錯誤可能進入的位置，再指定能區分原因的量測。"],"pitfallsEn":["Mixing wet and dry bases overstates recovered material or loading. Mark where this error can enter the Bottom-ash batches and metal basis flow and name a measurement that distinguishes causes.","Wet agglomeration retains recoverable fines in the coarse stream. Mark where this error can enter the Size classes and screening flow and name a measurement that distinguishes causes.","A heavier product may merely contain more non-metal contamination. Mark where this error can enter the Ferromagnetic metal recovery flow and name a measurement that distinguishes causes.","Entrained wet fines or minerals increase apparent mass while reducing product quality. Mark where this error can enter the Nonferrous eddy-current separation flow and name a measurement that distinguishes causes.","Comparing wet masses can mistake dewatering for solids removal. Mark where this error can enter the Moisture and adhering fines flow and name a measurement that distinguishes causes.","A heavier product may merely contain more non-metal contamination. Mark where this error can enter the Fine-metal losses flow and name a measurement that distinguishes causes.","Labelling leachate mg/L as solid mg/kg changes the interpretation. Mark where this error can enter the Leaching of mineral products flow and name a measurement that distinguishes causes.","Multiplying standard concentration by actual volume flow creates systematic bias. Mark where this error can enter the Dust collection and escape flow and name a measurement that distinguishes causes.","Mixing factors across years or boundaries creates misleading comparisons. Mark where this error can enter the Separation electricity and resource benefit flow and name a measurement that distinguishes causes.","Repeating measurements with the same bias does not remove systematic error. Mark where this error can enter the Grade-recovery handoff flow and name a measurement that distinguishes causes."],"sourceIds":["v17s-waste-wi","v17s-waste-wiindex","v17s-waste-tclp"],"sources":[{"id":"v17s-waste-wi","title":"歐盟 JRC 廢棄物焚化 BREF（2019）","titleEn":"JRC Waste Incineration BREF (2019)","url":"https://publications.jrc.ec.europa.eu/repository/handle/JRC118637","organization":"European Commission Joint Research Centre","accessed":"2026-10-23","publisher":"European Commission Joint Research Centre","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-waste-wiindex","title":"歐盟廢棄物焚化技術參考入口","titleEn":"EU Waste Incineration reference","url":"https://bureau-industrial-transformation.jrc.ec.europa.eu/reference/waste-incineration-0","organization":"European Commission Joint Research Centre","accessed":"2026-10-23","publisher":"European Commission Joint Research Centre","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-waste-tclp","title":"EPA SW-846 方法 1311：TCLP","titleEn":"EPA SW-846 Method 1311: TCLP","url":"https://www.epa.gov/hw-sw846/sw-846-test-method-1311-toxicity-characteristic-leaching-procedure","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."}],"simulationOnly":true,"scope":"公開原理與資料支持的原創教學。算例中的輸入為明示教學假設，非該設施實測或操作設定。此處任務在離線模型完成，不能作為現場設計、飲用水合格或設備操作許可。","scopeEn":"Original teaching based on public principles and sources. Numerical inputs are explicit teaching assumptions, not site measurements or operating setpoints. Tasks use offline models and do not certify field design, potable-water compliance or equipment operation."}]}]},"related":{"courses":[{"courseId":"b481","overview":"跨單元連結與比較練習","overviewEn":"Cross-process connections and comparisons","related":[{"id":"b407","title":"哥本哈根阿邁厄巴克焚化發電廠","titleEn":"Copenhagen Amager Bakke waste-to-energy plant","why":"比較兩個系統的物質或能量收支，列出不可直接沿用的邊界條件。","whyEn":"Compare material or energy balances and identify boundary conditions that cannot be transferred.","transfer":"守恆、量測與失效驗證","transferEn":"Conservation, measurement and failure verification","difference":"設備尺度、進料組成與品質目標必須分別設定。","differenceEn":"Equipment scale, feed composition and quality objectives require separate definitions.","practice":["各選一個教學算例，記下輸入、輸出與單位。","對照兩課的系統邊界，說明哪些假設不能沿用。","改變一個輸入，提出量測與失效判據來核對結果。"],"practiceEn":["Choose one worked example from each course and record inputs, outputs and units.","Compare system boundaries and identify assumptions that cannot transfer.","Change one input and propose measurements and failure criteria to check the result."],"place":{"name":"哥本哈根代表點","nameEn":"Copenhagen reference point","country":"丹麥","countryEn":"Denmark","lat":55.68,"lon":12.57,"coordinateScope":"approximate-city-reference; not a facility entrance","lng":12.57,"coordinateScopeEn":"Approximate public facility/research reference, not an operating entrance or the teaching laboratory."},"referenceUrls":["https://www.epa.gov/sustainable-water-infrastructure/research-innovative-and-alternative-wastewater-technologies","https://www.epa.gov/smm","https://www.epa.gov/septic/wastewater-technology-fact-sheets"]},{"id":"b413","title":"台北北投垃圾焚化廠","titleEn":"Taipei Beitou Refuse Incineration Plant","why":"比較兩個系統的物質或能量收支，列出不可直接沿用的邊界條件。","whyEn":"Compare material or energy balances and identify boundary conditions that cannot be transferred.","transfer":"守恆、量測與失效驗證","transferEn":"Conservation, measurement and failure verification","difference":"設備尺度、進料組成與品質目標必須分別設定。","differenceEn":"Equipment scale, feed composition and quality objectives require separate definitions.","practice":["各選一個教學算例，記下輸入、輸出與單位。","對照兩課的系統邊界，說明哪些假設不能沿用。","改變一個輸入，提出量測與失效判據來核對結果。"],"practiceEn":["Choose one worked example from each course and record inputs, outputs and units.","Compare system boundaries and identify assumptions that cannot transfer.","Change one input and propose measurements and failure criteria to check the result."],"place":{"name":"臺北都會區","nameEn":"Taipei metropolitan area","country":"臺灣","countryEn":"Taiwan","lat":25.04,"lon":121.52,"coordinateScope":"approximate-city-reference; not a facility entrance","lng":121.52,"coordinateScopeEn":"Approximate public facility/research reference, not an operating entrance or the teaching laboratory."},"referenceUrls":["https://www.epa.gov/sustainable-water-infrastructure/research-innovative-and-alternative-wastewater-technologies","https://www.epa.gov/smm","https://www.epa.gov/septic/wastewater-technology-fact-sheets"]}],"references":[{"id":"b-src-environment","title":"Research on Innovative and Alternative Wastewater Technologies","url":"https://www.epa.gov/sustainable-water-infrastructure/research-innovative-and-alternative-wastewater-technologies","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: wastewater technologies and treatment references. Not individual verification of every named environmental project."},{"id":"b-src-waste","title":"Sustainable Materials Management","url":"https://www.epa.gov/smm","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: materials life cycles, waste prevention, recycling and recovery."},{"id":"b-src-wastewater","title":"Wastewater Technology Fact Sheets","url":"https://www.epa.gov/septic/wastewater-technology-fact-sheets","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: disinfection, constructed wetlands, package plants, sewer technologies and treatment."},{"id":"v17s-waste-wi","title":"歐盟 JRC 廢棄物焚化 BREF（2019）","titleEn":"JRC Waste Incineration BREF (2019)","url":"https://publications.jrc.ec.europa.eu/repository/handle/JRC118637","organization":"European Commission Joint Research Centre","accessed":"2026-10-23","publisher":"European Commission Joint Research Centre","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-waste-wiindex","title":"歐盟廢棄物焚化技術參考入口","titleEn":"EU Waste Incineration reference","url":"https://bureau-industrial-transformation.jrc.ec.europa.eu/reference/waste-incineration-0","organization":"European Commission Joint Research Centre","accessed":"2026-10-23","publisher":"European Commission Joint Research Centre","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-waste-tclp","title":"EPA SW-846 方法 1311：TCLP","titleEn":"EPA SW-846 Method 1311: TCLP","url":"https://www.epa.gov/hw-sw846/sw-846-test-method-1311-toxicity-characteristic-leaching-procedure","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."}]}]},"places":{"courses":[{"courseId":"b481","place":{"name":"教學參考區域：美國北卡羅來納研究三角園區（非本課實拍場址）","nameEn":"Reference region: Research Triangle Park, North Carolina (not a photographed course facility)","country":"美國","countryEn":"United States","lat":35.9,"lon":-78.9,"scope":"Approximate institutional reference region; not a facility entrance, installation location or visitor permission.","lng":-78.9,"coordinateScope":"公開設施或研究據點的近似代表位置；不是操作入口或實際教學實驗室。","coordinateScopeEn":"Approximate public facility/research reference, not an operating entrance or the teaching laboratory."},"summary":"這項技術的學習脈絡由單一設備處理，逐步擴展至物質與能量收支、監測品質和生命週期比較。本課將官方方法文件作為查核入口，並以獨立編寫的假想數據練習；參考文件的年代與地區不代表其規範在所有場址適用。","summaryEn":"The learning progression expands from individual treatment equipment to mass and energy balances, monitoring quality and lifecycle comparison. Official method documents provide verification starting points while independently authored hypothetical data support practice; a document date or jurisdiction does not establish applicability to every site.","history":[{"year":"工程背景","title":"焚化底渣金屬回收","titleEn":"Metal recovery from incinerator bottom ash","text":"這項技術的學習脈絡由單一設備處理，逐步擴展至物質與能量收支、監測品質和生命週期比較。本課將官方方法文件作為查核入口，並以獨立編寫的假想數據練習；參考文件的年代與地區不代表其規範在所有場址適用。","textEn":"The learning progression expands from individual treatment equipment to mass and energy balances, monitoring quality and lifecycle comparison. Official method documents provide verification starting points while independently authored hypothetical data support practice; a document date or jurisdiction does not establish applicability to every site."}],"connection":"本課以「以粒徑、解離度和品位回收率設計底渣金屬分選的教學流程」為主軸，依序處理底渣批次與金屬基準、鐵磁性金屬回收、含水與細泥附著、礦物產物浸出評估、分選用電與資源效益。十個單元各包含機制、算例、量測驗證及失效診斷；數值均為明示的原創教學假設，不能直接用作工程設計、排放限值或設備設定。","connectionEn":"This course focuses on Build a bottom-ash metal-separation workflow around size, liberation and grade-recovery evidence, progressing through Bottom-ash batches and metal basis, Ferromagnetic metal recovery, Moisture and adhering fines, Leaching of mineral products, Separation electricity and resource benefit. Ten units each address mechanism, worked calculation, measurement verification and failure diagnosis. Numbers are explicit original teaching assumptions, not design values, emission limits or equipment settings.","references":[{"id":"v17s-waste-wi","title":"歐盟 JRC 廢棄物焚化 BREF（2019）","titleEn":"JRC Waste Incineration BREF (2019)","url":"https://publications.jrc.ec.europa.eu/repository/handle/JRC118637","organization":"European Commission Joint Research Centre","accessed":"2026-10-23","publisher":"European Commission Joint Research Centre","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-waste-wiindex","title":"歐盟廢棄物焚化技術參考入口","titleEn":"EU Waste Incineration reference","url":"https://bureau-industrial-transformation.jrc.ec.europa.eu/reference/waste-incineration-0","organization":"European Commission Joint Research Centre","accessed":"2026-10-23","publisher":"European Commission Joint Research Centre","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-waste-tclp","title":"EPA SW-846 方法 1311：TCLP","titleEn":"EPA SW-846 Method 1311: TCLP","url":"https://www.epa.gov/hw-sw846/sw-846-test-method-1311-toxicity-characteristic-leaching-procedure","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."}],"sourceIds":["v17s-waste-wi","v17s-waste-wiindex","v17s-waste-tclp"]}]},"vendors":{"courses":[],"vendors":[]}}};
